mapper.insert:
INSERT INTO tb_order_result(
  "uuid"
  , side
  , ord_type
  , price
  , state
  , market
  , created_at
  , volume
  , remaining_volume
  , reserved_fee
  , remaining_fee
  , paid_fee
  , "locked"
  , executed_volume
  , trades_count
) VALUES

  (
    #{item.uuid}
    , #{item.side}
    , #{item.ordType}
    , #{item.price}
    , #{item.state}
    , #{item.market}
    , #{item.createdAt}
    , #{item.volume}
    , #{item.remainingVolume}
    , #{item.reservedFee}
    , #{item.remainingFee}
    , #{item.paidFee}
    , #{item.locked}
    , #{item.executedVolume}
    , #{item.tradesCount}
  )

ON CONFLICT ("uuid")
DO UPDATE
SET price = EXCLUDED.price
    , volume = EXCLUDED.volume
